  "\n  query TeamQuery($projectId: Int!) {\n    moped_project_by_pk(project_id: $projectId) {\n      project_id\n      moped_proj_personnel(\n        where: { is_deleted: { _eq: false } }\n        order_by: { project_personnel_id: asc }\n      ) {\n        notes\n        project_personnel_id\n        created_at\n        created_by_user_id\n        is_deleted\n        moped_user {\n          first_name\n          last_name\n          user_id\n          is_deleted\n          email\n          moped_workgroup {\n            workgroup_id\n            workgroup_name\n          }\n        }\n        moped_proj_personnel_roles(where: { is_deleted: { _eq: false } }) {\n          id\n          project_personnel_id\n          project_role_id\n          moped_project_role {\n            project_role_id\n            project_role_name\n            project_role_description\n          }\n        }\n      }\n    }\n    moped_project_roles(\n      order_by: { project_role_name: asc }\n      where: { active_role: { _eq: true } }\n    ) {\n      project_role_id\n      project_role_name\n      project_role_description\n    }\n    moped_users(\n      order_by: { last_name: asc }\n      where: { is_deleted: { _eq: false } }\n    ) {\n      first_name\n      last_name\n      workgroup_id\n      user_id\n      is_deleted\n      email\n    }\n    moped_workgroup(\n      order_by: { workgroup_id: asc }\n      where: { is_deleted: { _eq: false } }\n    ) {\n      workgroup_id\n      workgroup_name\n    }\n  }\n": typeof types.TeamQueryDocument;
